package com.example.billing.api;import static com.example.billing.api.Contracts.*;import com.example.billing.service.CatalogService;import java.net.URI;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/catalog")public class CatalogController{private final CatalogService s;public CatalogController(CatalogService s){this.s=s;}@PostMapping("/products")ResponseEntity<?> createProduct(@RequestBody CreateProductRequest r){try{var x=s.createProduct(r);return ResponseEntity.created(URI.create("/catalog/products/"+x.id())).body(x);}catch(IllegalArgumentException e){return bad("invalid_product",e);}}@GetMapping("/products/{id}")ResponseEntity<?> getProduct(@PathVariable UUID id){var x=s.getProduct(id);return x==null?notFound("product_not_found","Product does not exist."):ResponseEntity.ok(x);}@GetMapping("/products")List<ProductResponse> listProducts(){return s.listProducts();}@PutMapping("/products/{id}")ResponseEntity<?> updateProduct(@PathVariable UUID id,@RequestBody CreateProductRequest r){try{var x=s.updateProduct(id,r);return x==null?notFound("product_not_found","Product does not exist."):ResponseEntity.ok(x);}catch(IllegalArgumentException e){return bad("invalid_product",e);}}@PostMapping("/products/{id}/deactivate")ResponseEntity<?> deactivateProduct(@PathVariable UUID id){var x=s.deactivateProduct(id);return x==null?notFound("product_not_found","Product does not exist."):ResponseEntity.ok(x);}@PostMapping("/price-plans")ResponseEntity<?> createPlan(@RequestBody CreatePricePlanRequest r){try{var x=s.createPlan(r);return ResponseEntity.created(URI.create("/catalog/price-plans/"+x.id())).body(x);}catch(IllegalArgumentException e){return bad("invalid_price_plan",e);}catch(IllegalStateException e){return bad("product_not_found",e);}}@GetMapping("/price-plans/{id}")ResponseEntity<?> getPlan(@PathVariable UUID id){var x=s.getPlan(id);return x==null?notFound("price_plan_not_found","Price plan does not exist."):ResponseEntity.ok(x);}@GetMapping("/price-plans")List<PricePlanResponse> listPlans(){return s.listPlans();}@PutMapping("/price-plans/{id}")ResponseEntity<?> updatePlan(@PathVariable UUID id,@RequestBody CreatePricePlanRequest r){try{var x=s.updatePlan(id,r);return x==null?notFound("price_plan_not_found","Price plan does not exist."):ResponseEntity.ok(x);}catch(IllegalArgumentException e){return bad("invalid_price_plan",e);}catch(IllegalStateException e){return bad("product_not_found",e);}}@PostMapping("/price-plans/{id}/deactivate")ResponseEntity<?> deactivatePlan(@PathVariable UUID id){var x=s.deactivatePlan(id);return x==null?notFound("price_plan_not_found","Price plan does not exist."):ResponseEntity.ok(x);}static ResponseEntity<ApiError> bad(String c,Exception e){return ResponseEntity.badRequest().body(new ApiError(c,e.getMessage()));}static ResponseEntity<ApiError> notFound(String c,String m){return ResponseEntity.status(404).body(new ApiError(c,m));}}
